import { createPermissionActor, createPermissionEngine, isOwner } from "@zudojs/permissions";

const engine = createPermissionEngine({
  roles: [
    { name: "member", permissions: ["task:read"], rules: [
      { name: "own-tasks", effect: "allow", resource: "task", action: "delete", condition: isOwner("userId") },
    ] },
    { name: "admin", permissions: ["task:*"] },
  ],
});
const tasks = new Map([[1, { id: 1, userId: "ada" }], [3, { id: 3, userId: "linus" }]]);
const userRoles = new Map([["ada", ["member"]], ["grace", ["admin"]]]);

async function deleteTask(userId, taskId) {
  if (!userId) return { status: 401 };
  const task = tasks.get(taskId);
  if (!task) return { status: 404 };
  const actor = createPermissionActor(userId, { roles: userRoles.get(userId) ?? [] });
  const decision = await engine.check(actor, "task:delete", task);
  if (!decision.allowed) return { status: 403, error: decision.publicReason };
  tasks.delete(task.id);
  return { status: 200, deleted: task.id };
}

console.log(await deleteTask(undefined, 3));
console.log(await deleteTask("ada", 3));
console.log(await deleteTask("ada", 9));
console.log(await deleteTask("ada", 1));
console.log(await deleteTask("grace", 3));

